/* Generated by `helix system machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type ToggleContext, type ToggleInput, counted, firm, lit, stuck, switchedOff, switchedOn } from './machine.js'

export type { ToggleContext, ToggleInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'toggle'

/** The state `off`. */
export const STATE_OFF = 0
/** The state `on`. */
export const STATE_ON = 1
/** Each state's name, by its number. */
export const STATES = ['off', 'on'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['off', 'on'] as const

/** The event `FLIP`. */
export const EVENT_FLIP = 0
/** The event `ASK`. */
export const EVENT_ASK = 1
/** Each event's name, by its number. */
export const EVENTS = ['FLIP', 'ASK'] as const

/** The effect `glow`. */
export const EFFECT_GLOW = 0
/** The effect `hum`. */
export const EFFECT_HUM = 1
/** The effect `say`. */
export const EFFECT_SAY = 2
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 3
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 4
/** Each effect's name, by its number. */
export const EFFECTS = ['glow', 'hum', 'say', 'deadline', 'deadline-end'] as const

/** The request event `before-turn`. */
export const ASK_BEFORE_TURN = 0
/** The request event `turn`. */
export const ASK_TURN = 1
/** Each request event's name, by its number. */
export const ASKS = ['before-turn', 'turn'] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: ToggleContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: ToggleContext): number =>
  lit(context) ? STATE_ON : STATE_OFF

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_OFF:
      return [[EFFECT_SAY]]
    case STATE_ON:
      return [[EFFECT_DEADLINE, { ms: 1000, owner: 1 }]]
  }
  return []
}

/** What `off` does with each event. */
const inOff = (context: ToggleContext, event: number, input: ToggleInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_FLIP:
      return { context: switchedOn(context), effects: [[EFFECT_GLOW], [EFFECT_DEADLINE, { ms: 1000, owner: 1 }]], state: STATE_ON }
    case EVENT_ASK:
      return firm(context, input) ? { accept: { context: switchedOn(context), effects: [[EFFECT_HUM, { level: 2, loud: true, tone: "low" }], [EFFECT_DEADLINE, { ms: 1000, owner: 1 }]], state: STATE_ON }, ask: [ASK_BEFORE_TURN, ASK_TURN], refuse: { context: counted(context, input), effects: [], state: STATE_OFF } } : undefined
  }
  return undefined
}

/** What `on` does with each event. */
const inOn = (context: ToggleContext, event: number, input: ToggleInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_FLIP:
      return stuck(context) ? { context: counted(context, input), effects: [], state: STATE_ON } : { context: switchedOff(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_GLOW], [EFFECT_SAY]], state: STATE_OFF }
    case EVENT_ASK:
      return { accept: { context: switchedOff(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_GLOW], [EFFECT_SAY]], state: STATE_OFF }, ask: [ASK_BEFORE_TURN], refuse: { context: context, effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_GLOW], [EFFECT_SAY], [EFFECT_DEADLINE, { ms: 1000, owner: 1 }]], state: STATE_ON } }
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: ToggleContext, event: number, input: ToggleInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_OFF:
      return inOff(context, event, input)
    case STATE_ON:
      return inOn(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: ToggleContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_ON:
      return owner === 1 ? { context: switchedOff(context), effects: [[EFFECT_DEADLINE_END, { owner: 1 }], [EFFECT_GLOW], [EFFECT_SAY], [EFFECT_SAY]], state: STATE_OFF } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: ToggleContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
